:root {
  --sunset-orange: #e8622a;
  --warm-sand: #f5ddb4;
  --deep-sky: #2b4c7e;
  --pale-dusk: #fdf0e0;
  --label-gray: #8a6e50;
  --white: #ffffff;
}

.hammock-tag {
  width: 260px;
  background-color: var(--pale-dusk);
  border: 2.5px solid var(--sunset-orange);
  border-radius: 16px;
  overflow: hidden;
  margin: 40px auto;
  font-size: 14px;
}

.tag-header {
  background-color: var(--sunset-orange);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
}

.tag-icon {
  font-size: 22px;
  line-height: 1;
}

.tag-title {
  color: var(--white);
  font-size: 17px;
  font-weight: 700;
  margin: 0;
  letter-spacing: 0.04em;
}

.tag-body {
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tag-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.tag-label {
  color: var(--label-gray);
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.tag-value {
  color: var(--deep-sky);
  font-size: 14px;
  font-weight: 700;
}

.tag-footer {
  background-color: var(--warm-sand);
  padding: 8px 16px;
  display: flex;
  justify-content: center;
}

.tag-status {
  color: var(--sunset-orange);
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  border: 1.5px solid var(--sunset-orange);
  border-radius: 20px;
  padding: 2px 14px;
}
